WHERE seller_id = #{sellerId}
ORDER BY created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT

FROM items
WHERE buyer_id = #{buyerId}
ORDER BY traded_at DESC, created_at DESC
